\title{The Local $\mathrm{GL}_2$ Frobenius Datum over $\mathbb{Q}$:\\
Eichler--Shimura Structure and Deligne's Weil Bound}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
We present a self-contained development of the \emph{local data} of the
Langlands correspondence for $\mathrm{GL}_2$ over $\Q$ at a good prime $p$, split
into its algebraic and analytic halves. On the algebraic side (Eichler--Shimura),
a weight-two Hecke eigenform attaches to each good prime $p$ a two-dimensional
Frobenius datum: a $2\times 2$ matrix with trace equal to the Hecke eigenvalue
$a_p$, determinant equal to $p$, characteristic polynomial equal to the Hecke
polynomial $X^2 - a_p X + p$, and satisfying the Eichler--Shimura congruence
relation, which at the level of the matrix is precisely the rank-2
Cayley--Hamilton identity $M^2 = a_p M - p\,I$. On the analytic side (Deligne /
Ramanujan--Petersson), the Frobenius eigenvalues are \emph{Weil numbers of weight
one}: they lie on the circle of radius $\sqrt p$. We isolate and rigorously prove
the \emph{real-algebraic core} of Deligne's theorem---that the two roots of a
monic real quadratic $X^2 - aX + p$ with $p>0$ lie on the circle $|z|=\sqrt p$ if
and only if $a^2 \le 4p$, equivalently $|a|\le 2\sqrt p$. This is the honest
finite shadow of Deligne's theorem (whose full force requires the Weil
conjectures). We derive the modulus of both Frobenius eigenvalues and of every
eigenvalue of the explicit companion matrix. All results have been formally
verified.
\end{abstract}

\section{Introduction}

The Langlands program predicts a correspondence between automorphic
representations and Galois representations. In its first nontrivial classical
case---weight-two cusp forms for $\mathrm{GL}_2$ over $\Q$---the correspondence
attaches to a Hecke eigenform $f$ a two-dimensional $\ell$-adic Galois
representation $\rho_f$ whose Frobenius at a good prime $p$ encodes the Hecke
eigenvalue $a_p$. The two structural pillars are:
\begin{enumerate}
  \item \textbf{Eichler--Shimura} (algebraic): at a good prime $p$ the local
  datum is a $2\times 2$ block with $\tr\Frob_p = a_p$ and $\det\Frob_p = p$,
  satisfying the Eichler--Shimura congruence relation.
  \item \textbf{Deligne / Ramanujan--Petersson} (analytic): the eigenvalues of
  $\Frob_p$ are Weil numbers of weight one, $|\cdot| = \sqrt p$.
\end{enumerate}
This paper isolates the purely structural and real-algebraic content of both
pillars, in an unconditional and elementary form, making precise the dictionary
\[
  X^2 - a_p X + p = \text{characteristic polynomial of } \Frob_p,
\]
constructing an explicit companion matrix realizing it, and proving
\[
  |a_p| \le 2\sqrt p \iff a_p^2 \le 4p \iff \big(\text{both roots lie on } |z| = \sqrt p\big).
\]
This is the $\mathrm{GL}_2$ refinement of the $\mathrm{GL}_1$ case, where the
local datum is a root of unity (absolute value $1$); here the unit circle is
replaced by the circle of radius $\sqrt p$.

\subsection{Conventions}
Throughout, $p > 0$ is real (the value of the cyclotomic character; a prime in
the arithmetic application) and $a \in \R$ (the Hecke eigenvalue). We write
$\|z\|$ for the complex absolute value and
$\normSq(z) = z\bar z = \Real(z)^2 + \Imag(z)^2$, so $\|z\| = \sqrt{\normSq(z)}$.
We use the principal real square root, with $\sqrt p = 0$ for $p \le 0$.

\section{Definitions}

\begin{definition}[Hecke polynomial]
For $a,p$ in a commutative ring $R$, the \emph{Hecke polynomial} is the monic
quadratic
\[
  \heckePoly(a,p) = X^2 - a X + p \in R[X],
\]
with evaluation $\heckePoly(a,p)(z) = z^2 - a z + p$.
\end{definition}

In the arithmetic setting $\heckePoly(a_p,p)$ is the characteristic polynomial of
geometric Frobenius at $p$ on $\rho_f$, and $(1 - a_p X + p X^2)^{-1}$ is the
local Euler factor of $L(f,s)$ (with $X = p^{-s}$).

\begin{definition}[Frobenius companion matrix]
The \emph{Frobenius companion matrix} of the Hecke polynomial is
\[
  \frobMatrix(a,p) = \begin{pmatrix} 0 & -p \\ 1 & a \end{pmatrix} \in M_2(R).
\]
\end{definition}

\begin{proposition}[Trace, determinant, characteristic polynomial]
\label{prop:trace}
$\tr\,\frobMatrix(a,p) = a$, $\det\,\frobMatrix(a,p) = p$, and the characteristic
polynomial of $\frobMatrix(a,p)$ is $\heckePoly(a,p) = X^2 - aX + p$.
\end{proposition}
\begin{proof}
The trace is $0 + a = a$ and the determinant is $0\cdot a - (-p)\cdot 1 = p$. For
the characteristic polynomial,
\[
  \det\!\begin{pmatrix} X & p \\ -1 & X - a\end{pmatrix} = X(X-a) + p = X^2 - aX + p. \qedhere
\]
\end{proof}

In particular $\lambda$ is an eigenvalue of $\frobMatrix(a,p)$ iff
$\heckePoly(a,p)(\lambda) = 0$, since
\begin{equation}\label{eq:det}
  \det\big(\frobMatrix(a,p) - \lambda I\big)
  = \det\!\begin{pmatrix} -\lambda & -p \\ 1 & a - \lambda \end{pmatrix}
  = -\lambda(a-\lambda) + p = \lambda^2 - a\lambda + p.
\end{equation}

\begin{definition}[Eichler--Shimura / Cayley--Hamilton form]
For $M = \frobMatrix(a,p)$, the local Eichler--Shimura congruence relation is the
identity $M^2 = a\,M - p\,I$, which is the Cayley--Hamilton theorem for $M$
(Proposition~\ref{prop:trace}).
\end{definition}

\begin{definition}[Weil number of weight one]
A complex number $z$ is a \emph{Weil number of weight one for $p$} if
$\|z\| = \sqrt p$, i.e.\ $z$ lies on the circle of radius $\sqrt p$.
\end{definition}

\section{Main Results}

\begin{theorem}[\texttt{deligne\_bound\_iff}]
\label{thm:bound}
For real $a,p$ with $p \ge 0$, $\;|a| \le 2\sqrt p \iff a^2 \le 4p$.
\end{theorem}
\begin{proof}
Since $p \ge 0$, $(\sqrt p)^2 = p$, hence $(2\sqrt p)^2 = 4p$. As $|a|\ge 0$ and
$2\sqrt p \ge 0$ and squaring is monotone on $[0,\infty)$,
$|a| \le 2\sqrt p \iff a^2 = |a|^2 \le (2\sqrt p)^2 = 4p$.
\end{proof}

\begin{theorem}[\texttt{deligne\_root\_abs}]
\label{thm:root}
Let $a,p \in \R$ with $p > 0$ and $a^2 \le 4p$. If $z \in \C$ satisfies
$\heckePoly(a,p)(z) = 0$, then $\|z\| = \sqrt p$.
\end{theorem}
\begin{proof}
Write $z = x + yi$. Taking real and imaginary parts of $z^2 - az + p = 0$:
\begin{align}
  x^2 - y^2 - a x + p &= 0, \label{eq:re}\\
  2xy - a y &= 0. \label{eq:im}
\end{align}
\emph{Case $y \ne 0$.} Equation~\eqref{eq:im} gives $y(2x-a) = 0$, so $a = 2x$.
Substituting into~\eqref{eq:re}: $-x^2 - y^2 + p = 0$, hence $x^2 + y^2 = p$, so
$\normSq(z) = p$.
\emph{Case $y = 0$.} Then~\eqref{eq:re} is $x^2 - ax + p = 0$, so
$(2x-a)^2 = a^2 - 4p \le 0$, forcing $a^2 = 4p$, $x = a/2$, $x^2 = p$; again
$\normSq(z) = p$. In both cases $\|z\| = \sqrt{\normSq(z)} = \sqrt p$.
\end{proof}

\begin{remark}[Necessity of $a^2 \le 4p$]
If $a^2 > 4p$ the roots are real and distinct, $\tfrac12(a\pm\sqrt{a^2-4p})$, with
product $p$ but different moduli, so the conclusion fails. The condition
$a^2 \le 4p$ is exactly the boundary between Weil-number and real-eigenvalue
behavior; the case split $y=0$ vs $y\neq 0$ is its formal trace.
\end{remark}

\begin{theorem}[\texttt{deligne\_weil\_pair}]
\label{thm:pair}
Let $a,p \in \R$ with $p > 0$ and $a^2 \le 4p$. If $\alpha,\beta \in \C$ satisfy
$\alpha + \beta = a$ and $\alpha\beta = p$, then $\alpha\beta = p$ and
$\|\alpha\| = \|\beta\| = \sqrt p$.
\end{theorem}
\begin{proof}
By Vieta, $\alpha,\beta$ are the roots of $X^2 - aX + p$: for
$\zeta\in\{\alpha,\beta\}$, $\zeta^2 - a\zeta + p = (\zeta-\alpha)(\zeta-\beta) = 0$.
Apply Theorem~\ref{thm:root} to each.
\end{proof}

\begin{theorem}[\texttt{deligne\_frob\_eigenvalues}]
\label{thm:frob}
Let $a,p \in \R$ with $p > 0$ and $a^2 \le 4p$. If $\lambda \in \C$ is an
eigenvalue of $\frobMatrix(a,p)$ over $\C$ (i.e.\ $\frobMatrix(a,p) - \lambda I$
is not invertible), then $\|\lambda\| = \sqrt p$.
\end{theorem}
\begin{proof}
Non-invertibility over a field gives $\det(\frobMatrix(a,p) - \lambda I) = 0$;
by~\eqref{eq:det} this equals $\lambda^2 - a\lambda + p = \heckePoly(a,p)(\lambda)$.
Apply Theorem~\ref{thm:root}.
\end{proof}

\section{Synthesis}

Combining the algebraic skeleton with the analytic bound gives both halves of the
local $\mathrm{GL}_2$ correspondence over $\Q$ at a good prime $p$: a $2\times 2$
Frobenius with trace $a_p$ and determinant $p$; characteristic polynomial
$X^2 - a_p X + p$ and Euler factor $(1 - a_p X + p X^2)^{-1}$; the
Eichler--Shimura relation $M^2 = a_p M - pI$; and Frobenius eigenvalues that are
Weil numbers of weight one, $\|\alpha\| = \|\beta\| = \sqrt p$, exactly when
$a_p^2 \le 4p$. This refines the $\mathrm{GL}_1$ picture (local datum a root of
unity, $|\cdot| = 1$) by replacing the unit circle with the circle of radius
$\sqrt p$.

\section{Algorithms}

\paragraph{Local datum and Deligne check.}
Given $(a,p)$ with $p>0$, form $M = \begin{pmatrix}0 & -p\\ 1 & a\end{pmatrix}$,
$\tr = a$, $\det = p$, $\mathrm{disc} = a^2 - 4p$, flag $a^2 \le 4p$; if the flag
holds, $|\alpha| = |\beta| = \sqrt p$ and the Sato--Tate angle is
$\theta = \arccos(a/(2\sqrt p)) \in [0,\pi]$, with
$\alpha = \sqrt p\, e^{i\theta}$, $\beta = \bar\alpha$.

\paragraph{Root modulus verification.}
Given a root $z = x+iy$ of $z^2 - az + p$: if $y\neq 0$ then $a = 2x$ and
$x^2 + y^2 = p$; if $y = 0$ then $(2x-a)^2 = a^2 - 4p \le 0$ and $x^2 = p$. Either
way $\|z\| = \sqrt p$.

\section{Applications}
\begin{itemize}
  \item \textbf{Modularity / Fermat's Last Theorem}: the two-dimensional Galois
  representations described here are matched to modular forms in the modularity
  theorem used by Wiles.
  \item \textbf{$L$-functions}: the Euler factor $(1 - a_p X + p X^2)^{-1}$
  assembles into $L(f,s)$; Theorem~\ref{thm:root} is the local Riemann
  Hypothesis.
  \item \textbf{Sato--Tate}: $a_p = 2\sqrt p\cos\theta_p$ with $\theta_p\in[0,\pi]$.
  \item \textbf{Point counting / cryptography}: for weight-two forms,
  $a_p = p + 1 - \#E(\mathbb{F}_p)$, and Theorem~\ref{thm:bound} is the Hasse
  bound.
\end{itemize}

\section{Discussion}
The content separates into an algebraic skeleton (formal: Cayley--Hamilton,
companion matrices, Vieta) and an analytic bound whose real-algebraic core
(Theorems~\ref{thm:bound}--\ref{thm:frob}) is elementary and unconditional, while
its full arithmetic force---that the actual Frobenius eigenvalues satisfy
$a^2 \le 4p$---is Deligne's theorem requiring the Weil conjectures. We make this
boundary explicit and exhibit that $a^2 \le 4p$ is exactly load-bearing. No
result is vacuous: Theorem~\ref{thm:root} is a genuine case analysis and
Theorem~\ref{thm:frob} applies to an honest companion matrix.

\section{Future Directions}

\begin{conjecture}[Local $L$-factor positivity / functional symmetry]
For $a^2 \le 4p$ the eigenvalues are complex conjugates, so $1 - aX + pX^2$
satisfies $\beta = p/\alpha = \bar\alpha$ and $X\mapsto 1/(pX)$ permutes the
reciprocal roots. Then $L_p(s) = (1 - a p^{-s} + p^{1-2s})^{-1}$ has no zeros in
$\Real(s) > 1/2$ exactly when $a^2 \le 4p$. The discriminant condition of
Theorem~\ref{thm:bound} is the boundary at which the reciprocal roots leave the
critical circle, so the local Riemann Hypothesis is equivalent to the Deligne
bound; what remains is a roots computation over $\C$.
\end{conjecture}

\begin{conjecture}[Sato--Tate angle surjectivity]
Writing $a = 2\sqrt p\cos\theta$, as $a$ ranges over $a^2 \le 4p$ the angle
$\theta$ ranges over all of $[0,\pi]$, and $a\mapsto\theta$ is a homeomorphism
$[-2\sqrt p, 2\sqrt p] \cong [0,\pi]$. Theorem~\ref{thm:root} pins every
eigenvalue to the circle of radius $\sqrt p$, leaving only the angle, and
Proposition~\ref{prop:trace}/Theorem~\ref{thm:frob} realize every admissible $a$;
the conjecture reduces to surjectivity of $\cos$ on $[0,\pi]$.
\end{conjecture}

\begin{conjecture}[Eichler--Shimura rigidity]
Two $2\times 2$ matrices over a field both satisfying $M^2 = aM - pI$ with the
same $(a,p)$ and $a^2 - 4p \ne 0$ are conjugate; equivalently, the local
Frobenius datum is determined by trace and determinant once the Hecke polynomial
is separable.
\end{conjecture}

